import React from "react";
import { Navbar, Nav, NavDropdown } from "react-bootstrap";

export const Navigation = (props) => {
  return (
    <nav id="menu" className="navbar navbar-default navbar-fixed-top">
      <div className="container">
      <div className="navbar-header">
      <Navbar.Brand href="#page-top">BAE LINK</Navbar.Brand>
       <ul className="navbar-right" >
          <Nav className="ml-auto" >
            {/* Collections Group */}
            <li>
            <NavDropdown title="Collections" id="collections-dropdown" className="nav navbar-nav navbar-right collapse navbar-collapse"> 
              <NavDropdown.Item href="#about" className="page-scroll">Col.About.1</NavDropdown.Item>
              <NavDropdown.Item href="#testimonials" className="page-scroll">Col.Testimonials.2</NavDropdown.Item>
              <NavDropdown.Item href="#team" className="page-scroll">Col.Team.3</NavDropdown.Item>
              <NavDropdown.Item href="#contact" className="page-scroll">Col.Contact.4</NavDropdown.Item>
            </NavDropdown>
            </li>
            {/* Brands Group */}
            <li>
            <NavDropdown title="Brands" id="brands-dropdown" className="nav navbar-nav navbar-right">
              <NavDropdown.Item href="#services">Brands</NavDropdown.Item>
            </NavDropdown>
            </li>
            {/* Gallery Group */}
            <NavDropdown title="Gallery" id="gallery-dropdown" className="nav navbar-nav navbar-right">
              <NavDropdown.Item href="#portfolio">Gallery</NavDropdown.Item>
            </NavDropdown>
          </Nav>
        </ul> 
      </div>
      </div>
    </nav>
  );
};
